#!/usr/bin/env node
// Copies compiled ABIs from ../contracts/out and deployment addresses from ../deployments
// into src/generated/ as typed TS modules (`as const` so viem infers argument/return types).
// If the sources are missing (fresh clone without `forge build`), the existing generated files are kept.
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const web = join(here, '..');
const outDir = join(web, '..', 'contracts', 'out');
const depDir = join(web, '..', 'deployments');
const genDir = join(web, 'src', 'generated');

const CONTRACTS = {
  FishingGame: 'fishingGameAbi',
  FishNFT: 'fishNftAbi',
  GameLens: 'gameLensAbi',
  PearlToken: 'pearlTokenAbi',
  Marketplace: 'marketplaceAbi',
  PearlExchange: 'pearlExchangeAbi',
};

mkdirSync(genDir, { recursive: true });
const header = '// AUTO-GENERATED by scripts/sync-abi.mjs — do not edit by hand. Run `pnpm sync`.\n';

let wroteAbi = 0;
for (const [name, exportName] of Object.entries(CONTRACTS)) {
  const src = join(outDir, `${name}.sol`, `${name}.json`);
  const dst = join(genDir, `${name}.ts`);
  if (!existsSync(src)) {
    if (existsSync(dst)) {
      console.warn(`[sync] ${src} not found, keeping existing ${name}.ts`);
      continue;
    }
    console.error(`[sync] ${src} not found. Run \`forge build\` in contracts/ first.`);
    process.exit(1);
  }
  const { abi } = JSON.parse(readFileSync(src, 'utf8'));
  writeFileSync(dst, `${header}export const ${exportName} = ${JSON.stringify(abi, null, 2)} as const;\n`);
  wroteAbi++;
}

const depDst = join(genDir, 'deployments.ts');
const deployments = {};
if (existsSync(depDir)) {
  for (const f of readdirSync(depDir)) {
    if (!/^\d+\.json$/.test(f)) continue;
    const d = JSON.parse(readFileSync(join(depDir, f), 'utf8'));
    deployments[String(d.chainId ?? f.replace('.json', ''))] = {
      chainId: Number(d.chainId),
      startBlock: Number(d.startBlock ?? 0),
      game: d.game,
      fish: d.fish,
      lens: d.lens,
      pearl: d.pearl,
      market: d.market,
      ...(d.blend && d.exchange ? { blend: d.blend, exchange: d.exchange } : {}),
    };
  }
}
if (!existsSync(depDir) && existsSync(depDst)) {
  console.warn('[sync] ../deployments not found, keeping existing deployments.ts');
} else {
  const type =
    'export interface Deployment {\n  chainId: number;\n  startBlock: number;\n  game: `0x${string}`;\n  fish: `0x${string}`;\n  lens: `0x${string}`;\n  pearl: `0x${string}`;\n  market: `0x${string}`;\n  /** Set once the BLEND → PEARL exchange is deployed. */\n  blend?: `0x${string}`;\n  exchange?: `0x${string}`;\n}\n';
  writeFileSync(
    depDst,
    `${header}${type}\nexport const deployments: Record<string, Deployment> = ${JSON.stringify(deployments, null, 2)};\n`,
  );
}

console.log(`[sync] ABIs: ${wroteAbi} written, deployments: ${Object.keys(deployments).join(', ') || 'none'}`);
